-- Assign 5 markets to all fixtures
INSERT INTO football.fixture_markets (fixture_id, market_id, outcomes)
SELECT f.id, pm.id,
  CASE pm.slug
    WHEN '1x2' THEN '["Home","Draw","Away"]'::jsonb
    WHEN 'btts' THEN '["Yes","No"]'::jsonb
    WHEN 'over-under-1-5' THEN '["Over 1.5","Under 1.5"]'::jsonb
    WHEN 'over-under-2-5' THEN '["Over 2.5","Under 2.5"]'::jsonb
    WHEN 'half-time-result' THEN '["Home","Draw","Away"]'::jsonb
  END
FROM football.fixtures f
CROSS JOIN football.prediction_markets pm
WHERE f.competition_id = '3465c662-745f-41a9-9385-ad537a4fd866'
  AND pm.slug IN ('1x2','btts','over-under-1-5','over-under-2-5','half-time-result')
ON CONFLICT DO NOTHING;
